  ["feature.bonus-proficiencies.psa2014.cleric.zeal-psa.1"]={title="Bonus Proficiencies",subtitle="Caracteristica - PSA - 2014",body="Pagina: 28\n\nAt 1st level, you gain proficiency with martial weapons and heavy armor."},
