  ["feature.bonus-proficiency.dmg2014.cleric.death.1"]={title="Bonus Proficiency",subtitle="Caracteristica - DMG - 2014",body="Pagina: 96\n\nWhen the cleric chooses this domain at 1st level, he or she gains proficiency with martial weapons."},
  ["feature.bonus-proficiency.phb2014.cleric.life.1"]={title="Bonus Proficiency",subtitle="Caracteristica - PHB - 2014",body=""},
